mapper.select:
select s.id, s.category_id, s.name, s.price, s.image, s.description, s.status, s.update_time, c.name as category_name from sky_take_out.setmeal as s join sky_take_out.category as c on s.category_id = c.id
and s.name like concat('%', #{name}, '%')
and s.category_id = #{categoryId}
and s.status = #{status}
order by s.category_id, s.id

select s.id, s.category_id, s.name, s.price, s.image, s.description, s.status, s.update_time, c.name as category_name from sky_take_out.setmeal as s join sky_take_out.category as c on s.category_id = c.id
and s.id = #{id}
order by s.category_id, s.id
